import { useCallback, useState, useEffect } from 'react';

// GLOBAL SINGLETONS to prevent AudioContext stacking
let globalAudioContext: AudioContext | null = null;
let globalGainNode: GainNode | null = null;

export const useSoundFX = () => {
  // Persist mute state
  const [isMuted, setIsMuted] = useState(() => {
    try {
      return localStorage.getItem('veritas_sound_muted') === 'true';
    } catch {
      return false;
    }
  });

  const toggleMute = useCallback(() => {
    setIsMuted(prev => {
      const newState = !prev;
      localStorage.setItem('veritas_sound_muted', String(newState));
      return newState;
    });
  }, []);

  const initAudio = useCallback(() => {
    if (!globalAudioContext) {
      const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
      globalAudioContext = new AudioContextClass();
      globalGainNode = globalAudioContext.createGain();
      globalGainNode.connect(globalAudioContext.destination);
    }
    if (globalAudioContext.state === 'suspended') {
      globalAudioContext.resume();
    }
    // Update gain based on mute state
    if (globalGainNode) {
      globalGainNode.gain.value = isMuted ? 0 : 0.1;
    }
  }, [isMuted]);

  // Sync gain with mute state changes
  useEffect(() => {
    if (globalGainNode) {
      globalGainNode.gain.value = isMuted ? 0 : 0.1;
    }
  }, [isMuted]);

  const playOscillator = (
    freq: number, 
    type: OscillatorType, 
    duration: number, 
    startTime: number = 0,
    vol: number = 0.1
  ) => {
    if (isMuted || !globalAudioContext || !globalGainNode) return;

    const osc = globalAudioContext.createOscillator();
    const gain = globalAudioContext.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, globalAudioContext.currentTime + startTime);

    gain.gain.setValueAtTime(vol, globalAudioContext.currentTime + startTime);
    gain.gain.exponentialRampToValueAtTime(0.01, globalAudioContext.currentTime + startTime + duration);

    osc.connect(gain);
    gain.connect(globalGainNode);

    osc.start(globalAudioContext.currentTime + startTime);
    osc.stop(globalAudioContext.currentTime + startTime + duration);
  };

  const playBlip = useCallback(() => {
    initAudio();
    playOscillator(1200, 'sine', 0.05);
  }, [initAudio, isMuted]);

  const playClick = useCallback(() => {
    initAudio();
    playOscillator(800, 'square', 0.01, 0, 0.05);
  }, [initAudio, isMuted]);

  const playKeystroke = useCallback(() => {
    // High-tech mechanical click
    if (isMuted || !globalAudioContext || !globalGainNode) return;
    // Don't init here to avoid lag on every char, assume initAudio called by parent

    // Simple noise burst simulation using high freq square
    const osc = globalAudioContext.createOscillator();
    const gain = globalAudioContext.createGain();

    // Randomize pitch slightly for organic feel
    osc.frequency.value = 800 + Math.random() * 200; 
    osc.type = 'square';

    // Very short duration
    gain.gain.setValueAtTime(0.02, globalAudioContext.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, globalAudioContext.currentTime + 0.03);

    osc.connect(gain);
    gain.connect(globalGainNode);

    osc.start();
    osc.stop(globalAudioContext.currentTime + 0.03);
  }, [isMuted]);

  const playActivate = useCallback(() => {
    initAudio();
    playOscillator(220, 'sawtooth', 0.3, 0, 0.05);
    playOscillator(440, 'sine', 0.3, 0.1, 0.05);
    playOscillator(880, 'square', 0.4, 0.2, 0.03);
  }, [initAudio, isMuted]);

  const playDataStream = useCallback(() => {
    initAudio();
    for(let i=0; i<5; i++) {
        playOscillator(1000 + Math.random() * 2000, 'square', 0.02, i * 0.03, 0.02);
    }
  }, [initAudio, isMuted]);

  const playVerdict = useCallback(() => {
    initAudio();
    const root = 261.63; // C4
    playOscillator(root, 'triangle', 1.5, 0, 0.1);
    playOscillator(root * 1.25, 'triangle', 1.5, 0.1, 0.1); // E4
    playOscillator(root * 1.5, 'triangle', 1.5, 0.2, 0.1); // G4
    playOscillator(root * 2, 'sine', 2.0, 0.3, 0.05); // C5
  }, [initAudio, isMuted]);

  const playError = useCallback(() => {
    initAudio();
    playOscillator(150, 'sawtooth', 0.4, 0, 0.1);
    playOscillator(140, 'sawtooth', 0.4, 0, 0.1);
  }, [initAudio, isMuted]);

  return {
    isMuted,
    toggleMute,
    playBlip,
    playClick,
    playKeystroke,
    playActivate,
    playDataStream,
    playVerdict,
    playError
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { useSoundFX } from '../features/reasoning/hooks/useSoundFX';

interface TerminalTextProps {
  text: string;
  speed?: number;
  className?: string;
  onComplete?: () => void;
  scramble?: boolean;
}

const CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?";

export const TerminalText: React.FC<TerminalTextProps> = ({ 
  text, 
  speed = 10, 
  className = "", 
  onComplete,
  scramble = true 
}) => {
  const [displayedText, setDisplayedText] = useState('');
  const [isComplete, setIsComplete] = useState(false);
  const iterationRef = useRef(0);
  const { playKeystroke } = useSoundFX();

  useEffect(() => {
    // Reset state when text changes
    setDisplayedText('');
    setIsComplete(false);
    iterationRef.current = 0;

    let interval: any;

    if (scramble) {
        // Scramble Effect for headers or short text
        interval = setInterval(() => {
            setDisplayedText(prev => {
                const result = text.split("").map((letter, index) => {
                    if (index < iterationRef.current) {
                        return text[index];
                    }
                    return CHARS[Math.floor(Math.random() * CHARS.length)];
                }).join("");

                if (iterationRef.current >= text.length) {
                    clearInterval(interval);
                    setIsComplete(true);
                    if (onComplete) onComplete();
                }

                iterationRef.current += 1/3; 
                return result;
            });
        }, 30);
    } else {
        // Standard Typewriter optimized for long text
        const effectiveSpeed = text.length > 200 ? 1 : speed;
        const step = text.length > 500 ? 5 : 1; 

        let i = 0;
        interval = setInterval(() => {
            setDisplayedText(text.slice(0, i + step));

            // Audio Feedback - trigger only occasionally to avoid spamming
            if (i % 3 === 0) playKeystroke();

            i += step;
            if (i >= text.length) {
                setDisplayedText(text); 
                clearInterval(interval);
                setIsComplete(true);
                if (onComplete) onComplete();
            }
        }, effectiveSpeed);
    }

    return () => clearInterval(interval);
  }, [text, speed, scramble, onComplete, playKeystroke]);

  return <span className={className}>{displayedText}{!isComplete && <span className="animate-pulse">_</span>}</span>;
};

import React, { useState } from 'react';

interface CodeBlockProps {
  code: string;
}

export const CodeBlock: React.FC<CodeBlockProps> = ({ code }) => {
  const [copied, setCopied] = useState(false);

  // Regex patterns for syntax highlighting
  const patterns = {
    keyword: /\b(const|let|var|function|return|if|else|for|while|import|export|from|class|interface|type|async|await)\b/g,
    string: /("[^"]*"|'[^']*'|`[^`]*`)/g,
    number: /\b(\d+)\b/g,
    comment: /(\/\/.*$|\/\*[\s\S]*?\*\/)/gm,
    boolean: /\b(true|false|null|undefined)\b/g,
    functionCall: /\b([a-zA-Z0-9_]+)(?=\()/g
  };

  const highlightCode = (input: string) => {
    let output = input
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");

    output = output
      .replace(patterns.string, '<span class="text-green-400">$1</span>')
      .replace(patterns.comment, '<span class="text-zinc-500 italic">$1</span>')
      .replace(patterns.keyword, '<span class="text-veritas-cyan font-bold">$1</span>')
      .replace(patterns.boolean, '<span class="text-veritas-red">$1</span>')
      .replace(patterns.number, '<span class="text-veritas-gold">$1</span>')
      .replace(patterns.functionCall, '<span class="text-blue-300">$1</span>');

    return output;
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
      <div className="my-3 bg-zinc-950 border border-zinc-800 rounded p-3 relative group">
        <div className="flex justify-between items-center mb-2 border-b border-zinc-900 pb-2">
            <span className="text-[9px] text-zinc-600 font-mono">SOURCE_FRAGMENT</span>
            <button 
                onClick={handleCopy}
                className="text-[9px] font-mono border border-zinc-800 hover:border-veritas-cyan hover:text-veritas-cyan px-2 py-0.5 rounded transition-all"
            >
                {copied ? 'COPIED_TO_CLIPBOARD' : 'COPY'}
            </button>
        </div>
        <div className="overflow-x-auto">
            <pre className="text-[11px] font-mono leading-relaxed whitespace-pre">
                <code className="text-zinc-300" dangerouslySetInnerHTML={{ __html: highlightCode(code) }} />
            </pre>
        </div>
      </div>
  );
};

